                    VALUES (@MobileDeviceProfileGuid,@SiteGuid,@ProfileID,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Description'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @Description END),@ShowProductScreen,@GenerateTicketNumber,@ShowOperatorFieldInFlightList,@UseDefaultPrinter,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DefaultPrinter'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DefaultPrinter END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('AdminPassword'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @AdminPassword END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShutdownHotKey'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ShutdownHotKey END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PrinterCOMPort'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @PrinterCOMPort END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SearchType'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @SearchType END),@LoggingOption,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('AllowableFailedLoginAttempts'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @AllowableFailedLoginAttempts END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('FuelDistributionPrecision'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @FuelDistributionPrecision END),@MakeDefaultProfile,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('VehicleID'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @VehicleID END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MonitorScreenTransitionTiming'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @MonitorScreenTransitionTiming END),@BypassFsrCheckOnScreenTrans,@ShowFuelUpdateCh