NDEX([sync].[udf_GetColumnSearchPattern]('Gate'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @Gate END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipNumber'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ShipNumber END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MeterTotal'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @MeterTotal END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('VolumePumped'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @VolumePumped END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TankCapacity'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @TankCapacity END),@EAStrictUserValidation,@EAVerifyFuelingEquipment,@EAAllowEditOfRequiredFuelLoad,@EAAllowBackAfterArrivalScreen,@EAAllowBackAfterTicketPrinted,@EARequirePrint,@EATotalFuelLoad,@EAVolumetricThresholdValidation,@EAValidateShipNumber,@EAAllowVTOModification,@EAAllowFlightGateModification,@EATankDiffPercentage,@EAWingBalancePercentage,@EABypassDistributionTolerance,@EAVehicleIDCheck,@EAGSEFuelMustMatch,@EAAllowManualMeter,@EAUseValidationLogicGATrans,@EAAllowShipNumberModification,@EAAllowAircraftTypeModification,@EAAllowDestinationModification,@EADestination,@EATicketPrinting,@EAAircraftType,@EAShipNumber,@EAGateNumber,@EAMeterTotal,@EAVolumePumped,@EATankCapacity,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EquipmentType'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @EquipmentType END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ForeignKeyToMapEquipment'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ForeignKeyToMapEquipment END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('IssueTransaction'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @IssueTransaction END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DefuelTransaction'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DefuelTransaction END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('RotationTransaction'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @RotationTransaction END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MeterCloseout'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @MeterCloseout END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DeIceTransaction'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DeIceTransaction END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('GSETransaction'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @GSETransaction END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualConsumer'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualConsumer END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualVendor'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualVendor END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualShipper'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualShipper END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualManager'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualManager END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualSupplier'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualSupplier END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualBillTo'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualBillTo END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualProduct'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualProduct END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CloseoutConsumer'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @CloseoutConsumer END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CloseoutOwner'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @CloseoutOwner END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CloseoutVendor'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @CloseoutVendor END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualStationID'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualStationID END),@InhibitOverridingTemperature,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualTemperature'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualTemperature END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ManualDensity'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ManualDensity END),@HasDCU,@BluetoothDCU,@LogDCUActions,@HasAveryHardoll,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DCUComPort'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DCUComPort END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DCUReadRetry'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DCUReadRetry END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DCUDisconnectDelay'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DCUDisconnectDelay END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DCUCommunicationFailRestart'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DCUCommunicationFailRestart END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('AveryHardollComPort'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @AveryHardollComPort END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('AveryHardollMeterID'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @AveryHardollMeterID END),@ConfirmFuelCaps,@VTOEnabled,@EnabledInOpGauges,@UseDispensingVehicleGSETrans,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('GSEWaitMSecForGetMeter'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @GSEWaitMSecForGetMeter END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('GSEInactiveLogoutMinutes'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @GSEInactiveLogoutMinutes END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('GSEInactiveTimeout'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @GSEInactiveTimeout END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('BarcodeInvalidWarningSeconds'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @BarcodeInvalidWarningSeconds END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DeIceBlendDefault'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @DeIceBlendDefault END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CommunicationTimeoutSeconds'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @CommunicationTimeoutSeconds END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ConnectionRetries'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ConnectionRetries END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ConnectionRetryTimeout'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ConnectionRetryTimeout END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ConnectionType'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @ConnectionType END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UpdateInterval'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @UpdateInterval END),@PingVerificationIPAddress,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('VehicleUpdateInterval'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @VehicleUpdateInterval END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PresubmitDelay'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @PresubmitDelay END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('VerificationIPAddress'), @sync_supported_columns_tblMobileDeviceProfile)) WHEN 0 THEN NULL ELSE @VerificationIPAddress END),@CreatedDate,@CreatedBy,@UpdatedDate,@UpdatedBy)
            ;
         SET @sync_row_count = @@rowcount;
    END
    ELSE
    BEGIN
          SET @sync_row_count = 1
    END

    -- If we updated / inserted a record here, go ahead and remove any pending conflict records associated with this ID because this record should contain the most recent data.
    IF (@sync_row_count > 0)
    BEGIN
        SET NOCOUNT ON
        IF EXISTS (SELECT 1 FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @MobileDeviceProfileGuid) AND SyncConflictResolutionStatusIndex IN (0,3))
        BEGIN
            DELETE FROM [sync].[tblSyncRecordConflictToSyncSessionScopeLog] WHERE SyncRecordConflictGuid IN (SELECT SyncRecordConflictGuid FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @MobileDeviceProfileGuid))
            DELETE FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @MobileDeviceProfileGuid)
        END
        SET NOCOUNT OFF
    END

    -- One issue with the MERGE approach is that we don't know if the @@rowcount is zero because of a true conflict now or if it was simply because
    -- the CreatedDate and UpdatedDate qualifiers were not met (in which case we want to simply throw away the update)
    -- In order to determine what took place, we're going to need to perform a query if @@rowcount = 0 to see if it was caused by the additional qualifiers.
    --
    IF (@sync_row_count = 0)
    BEGIN
        IF EXISTS (SELECT 1 FROM [dbo].[tblMobileDeviceProfile] WHERE MobileDeviceProfileGuid = @MobileDeviceProfileGuid AND (CreatedDate >= @CreatedDate OR UpdatedDate >= @UpdatedDate))
            SET @sync_row_count = 1;
    END
    
    SET @minValidVersion = 0;   -- This is used to detect Change Tracking cleanup
                                -- If we support this, we should add a column to SynchronizationTable
                                -- that records the MinValidVersion after change tracking information for
                                -- a table gets cleaned up.  I don't think this will be necessary.
    
    IF @minValidVersion > @sync_last_received_anchor 
        RAISERROR(N'(SU)Time between synchronization has exceeded the maximum amount of time for table ''%s'' (MIN: %I64d, LAST: %I64d).  To avoid data corruption and old data, the client must reinitialize its local database with a current refresh from the server.', 16, 3, @sync_table_name, @minValidVersion, @sync_last_received_anchor)
END
